insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('que-cultivos-se-adaptan-mejor-a-tu-localidad','agricultura',array[]::text[],'¿Qué cultivos se adaptan mejor a tu localidad?','Investiga qué cultivos crecen mejor en tu localidad según su clima, altitud y suelo, usando datos públicos, y explica por qué esos y no otros.','Investigación','3 semanas',22,array['Clima y cultivos','Adaptación local']::text[],array['investigar']::text[],'publicos',NULL,'agronomia ingenieria ambiental geografia estadistica ciencia de datos ingenieria agricola fisica ingenieria de sistemas busqueda de datos publicos. relacion entre variables. sintesis. comunicacion. datos oficiales de clima. hoja de calculo. un mapa sencillo.',$a12agr${"id": "que-cultivos-se-adaptan-mejor-a-tu-localidad", "area": "agricultura", "areas2": [], "titulo": "¿Qué cultivos se adaptan mejor a tu localidad?", "resumen": "Investiga qué cultivos crecen mejor en tu localidad según su clima, altitud y suelo, usando datos públicos, y explica por qué esos y no otros.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Clima y cultivos", "Adaptación local"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Agronomía", "Ingeniería Ambiental", "Geografía", "Estadística", "Ciencia de Datos", "Ingeniería Agrícola", "Física", "Ingeniería de Sistemas"], "problema": ["No todo cultivo crece bien en todas partes: lo que prospera en la costa puede fallar en la sierra. A veces se insiste en sembrar lo que está de moda y se ignoran cultivos locales que se adaptan mejor.", "Conocer las condiciones del lugar ayuda a elegir con más acierto y a valorar lo que ya se cultiva."], "desarrollar": ["Reúne datos públicos del clima, la altitud y el tipo de suelo de tu localidad. Identifica los cultivos que se producen allí y averigua qué condiciones necesita cada uno.", "Compara lo que necesita cada cultivo con lo que ofrece tu zona y elabora una lista de los más adecuados. Explica en una página por qué se adaptan, y qué otros cultivos serían un desafío y por qué."], "ampliaciones": [{"titulo": "Comparar localidades", "aporta": "repite el análisis para otra zona y compara."}, {"titulo": "Cultivos nativos", "aporta": "incluye cultivos tradicionales de la zona y su importancia."}, {"titulo": "Mapa", "aporta": "dibuja un mapa sencillo con los cultivos según la altitud."}], "objetivos": ["Reunir datos del lugar.", "Relacionar cultivos y condiciones.", "Identificar los más adecuados.", "Explicar las razones."], "habilidades": ["Búsqueda de datos públicos.", "Relación entre variables.", "Síntesis.", "Comunicación."], "herramientas": ["Datos oficiales de clima.", "Hoja de cálculo.", "Un mapa sencillo."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Aclara que es un panorama general y que la decisión de qué sembrar la toman quienes conocen el terreno."], "otroSector": "El mismo análisis de adaptación sirve para decidir dónde ubicar un negocio o qué producto ofrecer según el entorno."}$a12agr$::jsonb,19),
('calendario-de-siembra-y-cosecha-para-pequenos-productores','agricultura',array['negocios']::text[],'Calendario de siembra y cosecha para pequeños productores','Elabora un calendario sencillo que muestre cuándo sembrar y cuándo cosechar los cultivos principales de una zona, para ayudar a un pequeño productor a organizar su trabajo y a decidir cuándo vender.','Guía','3 semanas',16,array['Calendario agrícola','Pequeños productores']::text[],array['crear','otro-sector']::text[],'publicos',NULL,'agronomia ingenieria ambiental geografia estadistica ciencia de datos ingenieria agricola fisica ingenieria de sistemas organizacion de datos. diseno de informacion. planificacion. comunicacion clara. datos publicos agrarios. hoja de calculo. un editor de graficos.',$a13agr${"id": "calendario-de-siembra-y-cosecha-para-pequenos-productores", "area": "agricultura", "areas2": ["negocios"], "titulo": "Calendario de siembra y cosecha para pequeños productores", "resumen": "Elabora un calendario sencillo que muestre cuándo sembrar y cuándo cosechar los cultivos principales de una zona, para ayudar a un pequeño productor a organizar su trabajo y a decidir cuándo vender.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 16, "etiquetas": ["Calendario agrícola", "Pequeños productores"], "intencion": ["crear", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Agronomía", "Ingeniería Ambiental", "Geografía", "Estadística", "Ciencia de Datos", "Ingeniería Agrícola", "Física", "Ingeniería de Sistemas"], "problema": ["Un productor pequeño debe decidir qué sembrar y cuándo, y también cuándo estará lista su cosecha para venderla. Si todos cosechan al mismo tiempo, el precio baja; si no se sabe cuándo habrá producto, se pierden oportunidades de venta.", "Un calendario claro ayuda a organizar el trabajo y a anticipar los momentos de más y menos producción."], "desarrollar": ["Elige cinco cultivos de una zona y, con datos públicos, anota los meses de siembra, el tiempo hasta la cosecha y los meses de cosecha. Marca los meses de mayor oferta y los de menor oferta.", "Diseña un calendario visual por cultivo y mes que sea fácil de leer, y agrega notas sobre los meses en que conviene vender o almacenar. Revisa que lo entienda alguien que no sea experto."], "ampliaciones": [{"titulo": "Calendario de precios", "aporta": "añade cómo varían los precios en los distintos meses."}, {"titulo": "Diversificar", "aporta": "propón qué cultivos sumar para repartir mejor las cosechas."}, {"titulo": "Versión impresa", "aporta": "adapta el calendario para colocarlo en una pared o en un tablón."}], "objetivos": ["Reunir datos de ciclos y meses.", "Marcar los picos de oferta.", "Diseñar un calendario claro.", "Probarlo con una persona usuaria."], "habilidades": ["Organización de datos.", "Diseño de información.", "Planificación.", "Comunicación clara."], "herramientas": ["Datos públicos agrarios.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Presenta el calendario como orientación y no como recomendación comercial.", "Si conversas con productores o vendedores, hazlo con su permiso, sin publicar nombres ni datos de contacto; si prefieren no participar, usa casos inventados."], "otroSector": "El mismo tipo de calendario sirve para planificar turnos, campañas o producción en cualquier rubro estacional."}$a13agr$::jsonb,20),
('una-compostera-casera-con-materiales-reutilizados','agricultura',array['ambiente']::text[],'Una compostera casera con materiales reutilizados','Construye una compostera pequeña con un balde o una caja reutilizada, mantén un registro de cómo cambia el material y evalúa si es práctica para una casa o un departamento.','Prototipo','4 semanas',18,array['Compostaje','Reutilización']::text[],array['crear','resolver']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental ingenieria quimica quimica ingenieria agroindustrial educacion nutricion construccion de prototipos. registro de observaciones. resolucion de problemas. documentacion. recipiente reutilizado. restos de cocina. cuaderno de campo.',$a14agr${"id": "una-compostera-casera-con-materiales-reutilizados", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Una compostera casera con materiales reutilizados", "resumen": "Construye una compostera pequeña con un balde o una caja reutilizada, mantén un registro de cómo cambia el material y evalúa si es práctica para una casa o un departamento.", "tipo": "Prototipo", "tiempo": "4 semanas", "horas": 18, "etiquetas": ["Compostaje", "Reutilización"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Ingeniería Química", "Química", "Ingeniería Agroindustrial", "Educación", "Nutrición"], "problema": ["Mucha gente quiere compostar pero cree que necesita un equipo caro o un terreno grande. Una compostera pequeña puede hacerse con materiales reutilizados, pero si no se cuida la humedad y la aireación, puede oler mal o atraer insectos.", "Probar un diseño casero permite saber qué funciona antes de invertir en algo mayor."], "desarrollar": ["Elige un recipiente reutilizado, hazle huecos para el aire y prepara capas de restos vegetales de cocina y material seco, como hojas o cartón. Colócalo en un lugar ventilado y a la sombra.", "Durante cuatro semanas registra la temperatura al tacto, la humedad, el olor y cuánto disminuye el volumen. Anota los problemas que aparecen y cómo los resolviste, y evalúa si el diseño es práctico para otras personas."], "ampliaciones": [{"titulo": "Dos diseños", "aporta": "construye otro diseño y compara cuál funciona mejor."}, {"titulo": "Ficha técnica", "aporta": "escribe una hoja con medidas, materiales y pasos."}, {"titulo": "Olores y plagas", "aporta": "documenta cómo evitaste olores o insectos."}], "objetivos": ["Construir la compostera.", "Registrar su evolución.", "Resolver problemas comunes.", "Evaluar su practicidad."], "habilidades": ["Construcción de prototipos.", "Registro de observaciones.", "Resolución de problemas.", "Documentación."], "herramientas": ["Recipiente reutilizado.", "Restos de cocina.", "Cuaderno de campo."], "lineamientos": ["No eches carne, lácteos ni restos cocinados con aceite en una compostera pequeña: atraen plagas y malos olores. Pide permiso para usar el espacio.", "Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Lávate las manos después de manipular el compost y mantén la compostera lejos de la comida y de las mascotas."], "otroSector": "El mismo ejercicio de transformar residuos sirve para pensar en reutilizar materiales en talleres y negocios pequeños."}$a14agr$::jsonb,21),
('guia-para-iniciar-tu-compostera','agricultura',array['ambiente']::text[],'Guía para iniciar tu compostera','Escribe una guía corta y clara para quien nunca ha compostado: qué se puede y qué no se puede echar, cómo cuidar la humedad, qué problemas aparecen y cómo saber que el compost está listo.','Guía','2 semanas',12,array['Compostaje','Guía práctica']::text[],array['crear']::text[],'publicos',NULL,'ingenieria ambiental agronomia educacion comunicaciones biologia diseno ingenieria quimica nutricion comunicacion clara. sintesis. diseno de informacion. prueba con usuarios. guias publicas. un editor de documentos. imagenes o dibujos propios.',$a15agr${"id": "guia-para-iniciar-tu-compostera", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Guía para iniciar tu compostera", "resumen": "Escribe una guía corta y clara para quien nunca ha compostado: qué se puede y qué no se puede echar, cómo cuidar la humedad, qué problemas aparecen y cómo saber que el compost está listo.", "tipo": "Guía", "tiempo": "2 semanas", "horas": 12, "etiquetas": ["Compostaje", "Guía práctica"], "intencion": ["crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Ambiental", "Agronomía", "Educación", "Comunicaciones", "Biología", "Diseño", "Ingeniería Química", "Nutrición"], "problema": ["Muchas personas abandonan el compostaje en la primera semana porque no saben qué hacer cuando huele mal, aparecen moscas o la mezcla no se descompone. Las guías disponibles suelen ser largas o llenas de términos técnicos.", "Una guía breve, visual y honesta sobre los problemas comunes ayuda a que más gente se anime y siga."], "desarrollar": ["Reúne información de guías públicas de municipalidades y universidades sobre compostaje doméstico. Elabora una lista de lo que sí y lo que no se debe echar, y de los problemas más frecuentes con sus soluciones.", "Diseña una guía de una o dos páginas con pasos simples, ilustraciones y una tabla de preguntas frecuentes. Pídele a alguien que nunca ha compostado que la lea y anota qué no entendió, para mejorarla."], "ampliaciones": [{"titulo": "Versión en cartel", "aporta": "adapta la guía a un cartel para pegar junto a la compostera."}, {"titulo": "Preguntas frecuentes", "aporta": "añade una sección de dudas con respuestas cortas."}, {"titulo": "Prueba con usuarios", "aporta": "recoge opiniones de tres personas y mejora el texto."}], "objetivos": ["Reunir información confiable.", "Redactar pasos claros.", "Diseñar la guía.", "Probarla con una persona nueva."], "habilidades": ["Comunicación clara.", "Síntesis.", "Diseño de información.", "Prueba con usuarios."], "herramientas": ["Guías públicas.", "Un editor de documentos.", "Imágenes o dibujos propios."], "lineamientos": ["No eches carne, lácteos ni restos cocinados con aceite en una compostera pequeña: atraen plagas y malos olores. Pide permiso para usar el espacio.", "Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Aclara que son recomendaciones generales y que cada lugar puede tener normas propias de residuos."], "otroSector": "La misma forma de explicar un proceso en pasos simples sirve para escribir manuales de cualquier trabajo o producto."}$a15agr$::jsonb,22),
('compostaje-tradicional-vs-con-lombrices','agricultura',array['ambiente']::text[],'Compostaje tradicional vs con lombrices','Compara dos formas de convertir restos de cocina en abono: el compostaje tradicional y el que usa lombrices, midiendo cuánto tardan, qué espacio necesitan y qué tan fáciles son de mantener.','Análisis','6 semanas',26,array['Compostaje','Vermicompostaje']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental ingenieria quimica quimica ingenieria agroindustrial educacion nutricion control de variables. observacion a lo largo del tiempo. comparacion. redaccion de conclusiones. recipientes reutilizados. restos de cocina. cuaderno de campo.',$a16agr${"id": "compostaje-tradicional-vs-con-lombrices", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Compostaje tradicional vs con lombrices", "resumen": "Compara dos formas de convertir restos de cocina en abono: el compostaje tradicional y el que usa lombrices, midiendo cuánto tardan, qué espacio necesitan y qué tan fáciles son de mantener.", "tipo": "Análisis", "tiempo": "6 semanas", "horas": 26, "etiquetas": ["Compostaje", "Vermicompostaje"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Ingeniería Química", "Química", "Ingeniería Agroindustrial", "Educación", "Nutrición"], "problema": ["El compostaje tradicional y el vermicompostaje, que usa lombrices, prometen abono a partir de residuos, pero se manejan distinto. Uno requiere voltear y controlar la humedad, el otro necesita cuidar a los animales y su temperatura.", "Comparar ambos permite saber cuál conviene más para un espacio pequeño y para alguien con poco tiempo."], "desarrollar": ["Prepara dos pequeños sistemas con la misma cantidad de restos vegetales. Uno será compostaje tradicional y el otro llevará lombrices rojas, que se consiguen en viveros. Registra durante varias semanas cómo cambia el volumen, el olor, la humedad y el tiempo que dedicas a cada uno.", "Compara en una tabla el esfuerzo, el espacio, los problemas y el aspecto del producto final de cada sistema. Concluye cuál recomendarías y para qué tipo de persona."], "ampliaciones": [{"titulo": "Calidad", "aporta": "evalúa cómo crece una planta con el abono de cada sistema."}, {"titulo": "Costos", "aporta": "compara cuánto cuesta montar cada sistema."}, {"titulo": "Tiempo de dedicación", "aporta": "mide cuántos minutos por semana exige cada uno."}], "objetivos": ["Montar dos sistemas comparables.", "Registrar su evolución.", "Comparar esfuerzo y resultados.", "Recomendar según el caso."], "habilidades": ["Control de variables.", "Observación a lo largo del tiempo.", "Comparación.", "Redacción de conclusiones."], "herramientas": ["Recipientes reutilizados.", "Restos de cocina.", "Cuaderno de campo."], "lineamientos": ["No eches carne, lácteos ni restos cocinados con aceite en una compostera pequeña: atraen plagas y malos olores. Pide permiso para usar el espacio.", "Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Trata bien a las lombrices: mantenlas en la sombra, con humedad adecuada y sin alimentos cítricos ni salados."], "otroSector": "El mismo método de comparar dos sistemas sirve para elegir entre dos procesos o herramientas en cualquier trabajo."}$a16agr$::jsonb,23),
('que-residuos-se-descomponen-mas-rapido','agricultura',array['ambiente']::text[],'¿Qué residuos se descomponen más rápido?','Compara cuánto tardan en descomponerse distintos restos vegetales, como cáscaras, hojas, cartón y restos de verdura, para saber qué conviene mezclar en una compostera.','Análisis','5 semanas',22,array['Descomposición','Residuos orgánicos']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental ingenieria quimica quimica ingenieria agroindustrial educacion nutricion diseno de pruebas simples. registro y pesaje. comparacion. explicacion de resultados. recipientes pequenos. balanza de cocina. camara del celular.',$a17agr${"id": "que-residuos-se-descomponen-mas-rapido", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Qué residuos se descomponen más rápido?", "resumen": "Compara cuánto tardan en descomponerse distintos restos vegetales, como cáscaras, hojas, cartón y restos de verdura, para saber qué conviene mezclar en una compostera.", "tipo": "Análisis", "tiempo": "5 semanas", "horas": 22, "etiquetas": ["Descomposición", "Residuos orgánicos"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Ingeniería Química", "Química", "Ingeniería Agroindustrial", "Educación", "Nutrición"], "problema": ["En una compostera no todo se descompone igual: unas cáscaras desaparecen en días y otros restos tardan semanas. Echar todo junto sin saber esto lleva a pilas desbalanceadas, con mal olor o con material que no se transforma.", "Medir qué se descompone más rápido permite preparar mejores mezclas."], "desarrollar": ["Selecciona cuatro o cinco tipos de restos vegetales y coloca la misma cantidad de cada uno en recipientes iguales con tierra o compost maduro. Si quieres, usa bolsitas de malla para poder sacarlos y observarlos sin mezclarlos.", "Cada semana pesa o fotografía cada muestra y anota cuánto queda. Ordénalos del que se descompone más rápido al más lento y explica por qué crees que ocurre, por ejemplo por su dureza o su humedad."], "ampliaciones": [{"titulo": "Cortar o no cortar", "aporta": "compara el mismo resto entero y en trozos pequeños."}, {"titulo": "Humedad", "aporta": "repite la prueba con más y menos humedad."}, {"titulo": "Receta de mezcla", "aporta": "propón una mezcla equilibrada según lo que observaste."}], "objetivos": ["Preparar muestras comparables.", "Registrar la descomposición.", "Ordenar los materiales.", "Proponer mezclas."], "habilidades": ["Diseño de pruebas simples.", "Registro y pesaje.", "Comparación.", "Explicación de resultados."], "herramientas": ["Recipientes pequeños.", "Balanza de cocina.", "Cámara del celular."], "lineamientos": ["No eches carne, lácteos ni restos cocinados con aceite en una compostera pequeña: atraen plagas y malos olores. Pide permiso para usar el espacio.", "Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Lávate las manos después de manipular las muestras y mantenlas lejos de la comida."], "otroSector": "El mismo tipo de prueba sirve para comparar cuánto tardan en degradarse distintos materiales de empaque o de construcción."}$a17agr$::jsonb,24),
('que-tan-bueno-es-el-compost-casero-calidad-y-efecto-en-las-plant','agricultura',array['ambiente']::text[],'¿Qué tan bueno es el compost casero? Calidad y efecto en las plantas','Evalúa el aspecto, el olor y la textura de un compost casero y compara cómo crece una misma planta con compost, sin compost y con tierra comprada, para saber si realmente ayuda.','Análisis','6 semanas',26,array['Compost','Calidad del abono']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental ingenieria quimica quimica ingenieria agroindustrial educacion nutricion observacion cualitativa. control de variables. graficas. pensamiento critico. compost casero. macetas. regla y hoja de calculo.',$a18agr${"id": "que-tan-bueno-es-el-compost-casero-calidad-y-efecto-en-las-plant", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Qué tan bueno es el compost casero? Calidad y efecto en las plantas", "resumen": "Evalúa el aspecto, el olor y la textura de un compost casero y compara cómo crece una misma planta con compost, sin compost y con tierra comprada, para saber si realmente ayuda.", "tipo": "Análisis", "tiempo": "6 semanas", "horas": 26, "etiquetas": ["Compost", "Calidad del abono"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Ingeniería Química", "Química", "Ingeniería Agroindustrial", "Educación", "Nutrición"], "problema": ["Se dice que el compost casero mejora el suelo, pero rara vez se comprueba. Un compost a medio hacer puede incluso perjudicar a las plantas, y no siempre es fácil saber cuándo está listo.", "Observar su calidad y probar su efecto en una planta permite saber si vale la pena usarlo."], "desarrollar": ["Cuando tu compost parezca listo, revisa su color, su olor a tierra, su textura y que no queden restos reconocibles. Siembra la misma planta en tres macetas: una con tierra sola, otra con tierra y compost y otra con tierra comprada.", "Mide la altura y cuenta las hojas durante varias semanas. Compara los resultados en una gráfica y concluye si el compost ayudó y en qué proporción, siendo honesto con las limitaciones del experimento."], "ampliaciones": [{"titulo": "Proporciones", "aporta": "prueba distintas cantidades de compost en la mezcla."}, {"titulo": "Prueba de germinación", "aporta": "siembra semillas en compost puro para ver si está maduro."}, {"titulo": "Guía para saber si está listo", "aporta": "crea una lista de señales para reconocer un compost maduro."}], "objetivos": ["Evaluar el compost.", "Preparar un experimento comparable.", "Medir el crecimiento.", "Concluir con cautela."], "habilidades": ["Observación cualitativa.", "Control de variables.", "Gráficas.", "Pensamiento crítico."], "herramientas": ["Compost casero.", "Macetas.", "Regla y hoja de cálculo."], "lineamientos": ["No eches carne, lácteos ni restos cocinados con aceite en una compostera pequeña: atraen plagas y malos olores. Pide permiso para usar el espacio.", "Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "No uses compost que huela a podrido en plantas comestibles, y lava lo que coseches."], "otroSector": "El mismo enfoque de evaluar calidad y probar un efecto sirve para revisar cualquier insumo o producto que promete mejoras."}$a18agr$::jsonb,25),
('compostaje-para-una-comunidad-o-una-institucion','agricultura',array['ambiente','sociedad']::text[],'Compostaje para una comunidad o una institución','Diseña cómo funcionaría un sistema de compostaje para un grupo grande, como un colegio, un mercado o un conjunto de vecinos: dónde, quién lo atiende, cuánto residuo recibe y qué se hace con el abono.','Plan','4 semanas',24,array['Compostaje comunitario','Residuos orgánicos']::text[],array['crear','resolver']::text[],'ficticios',NULL,'ingenieria ambiental agronomia trabajo social gestion de proyectos administracion educacion ingenieria industrial comunicaciones planificacion de procesos. estimacion. organizacion de equipos. comunicacion. hoja de calculo. diagrama de flujo. un documento de plan.',$a19agr${"id": "compostaje-para-una-comunidad-o-una-institucion", "area": "agricultura", "areas2": ["ambiente", "sociedad"], "titulo": "Compostaje para una comunidad o una institución", "resumen": "Diseña cómo funcionaría un sistema de compostaje para un grupo grande, como un colegio, un mercado o un conjunto de vecinos: dónde, quién lo atiende, cuánto residuo recibe y qué se hace con el abono.", "tipo": "Plan", "tiempo": "4 semanas", "horas": 24, "etiquetas": ["Compostaje comunitario", "Residuos orgánicos"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería Ambiental", "Agronomía", "Trabajo Social", "Gestión de Proyectos", "Administración", "Educación", "Ingeniería Industrial", "Comunicaciones"], "problema": ["Compostar en casa es sencillo, pero hacerlo para muchas personas requiere organización: dónde se recolectan los residuos, quién voltea el material, qué pasa con los olores y quién usa el abono. Sin un plan, el sistema se llena o se abandona.", "Pensar el proceso completo antes de empezar evita problemas y ayuda a convencer a quienes deben aprobarlo."], "desarrollar": ["Elige una institución o grupo, real o imaginario, y estima cuántos residuos orgánicos genera por semana con datos de ejemplo. Define dónde se colocará la zona de compostaje, qué recipientes se usarán y quiénes se encargarán de cada tarea.", "Dibuja el flujo desde que se separa el residuo hasta que se usa el abono, y calcula el espacio, el tiempo y los materiales necesarios. Elabora un plan breve con cronograma, riesgos y formas de comunicar las reglas a los participantes."], "ampliaciones": [{"titulo": "Costos", "aporta": "estima los costos de montar y mantener el sistema."}, {"titulo": "Capacitación", "aporta": "diseña una charla corta para enseñar a separar bien los residuos."}, {"titulo": "Uso del abono", "aporta": "propón cómo se aprovecharía el compost en un jardín o huerto de la institución."}], "objetivos": ["Estimar la cantidad de residuos.", "Diseñar el flujo y los roles.", "Calcular recursos.", "Planear la comunicación."], "habilidades": ["Planificación de procesos.", "Estimación.", "Organización de equipos.", "Comunicación."], "herramientas": ["Hoja de cálculo.", "Diagrama de flujo.", "Un documento de plan."], "lineamientos": ["No eches carne, lácteos ni restos cocinados con aceite en una compostera pequeña: atraen plagas y malos olores. Pide permiso para usar el espacio.", "Consulta las normas locales de manejo de residuos antes de proponer algo real.", "Usa datos de ejemplo y no incluyas información de personas."], "otroSector": "El mismo diseño de flujo y de roles sirve para organizar el reciclaje, la recolección o la limpieza en cualquier lugar."}$a19agr$::jsonb,26),
('cuanto-compost-puede-producir-un-hogar','agricultura',array['ambiente']::text[],'¿Cuánto compost puede producir un hogar?','Mide cuántos restos vegetales genera tu hogar en unas semanas y estima cuánto compost podrían producir, para saber qué tan grande debería ser una compostera y qué porcentaje de tu basura se aprovecharía.','Análisis','3 semanas',18,array['Residuos del hogar','Estimaciones']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental ingenieria quimica quimica ingenieria agroindustrial educacion nutricion medicion. calculo de promedios. estimacion. graficas. balanza de cocina. cuaderno de registro. hoja de calculo.',$a20agr${"id": "cuanto-compost-puede-producir-un-hogar", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Cuánto compost puede producir un hogar?", "resumen": "Mide cuántos restos vegetales genera tu hogar en unas semanas y estima cuánto compost podrían producir, para saber qué tan grande debería ser una compostera y qué porcentaje de tu basura se aprovecharía.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 18, "etiquetas": ["Residuos del hogar", "Estimaciones"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Ingeniería Química", "Química", "Ingeniería Agroindustrial", "Educación", "Nutrición"], "problema": ["Se habla de que el compostaje reduce la basura, pero pocas personas saben cuánto genera su hogar. Sin esa medida, es difícil decidir el tamaño de la compostera o saber si realmente vale la pena el esfuerzo.", "Medir los propios residuos convierte una idea abstracta en números concretos."], "desarrollar": ["Durante dos o tres semanas, separa los restos vegetales de tu cocina, como cáscaras y restos de frutas y verduras, y pésalos cada día o cada pocos días. Anota también cuánta basura total generaste, si es posible.", "Calcula el promedio semanal y estima cuánto compost resultaría, considerando que el material se reduce al descomponerse. Presenta tu estimación en una tabla y una gráfica y explica qué tamaño de compostera necesitarías."], "ampliaciones": [{"titulo": "Por persona", "aporta": "calcula cuánto residuo orgánico genera cada integrante del hogar."}, {"titulo": "Proyección anual", "aporta": "estima cuánto abono y cuánta basura se evitaría en un año."}, {"titulo": "Comparar hogares", "aporta": "compara con el registro de otros hogares, de forma anónima y con permiso."}], "objetivos": ["Registrar los residuos.", "Calcular promedios.", "Estimar el compost.", "Dimensionar la compostera."], "habilidades": ["Medición.", "Cálculo de promedios.", "Estimación.", "Gráficas."], "herramientas": ["Balanza de cocina.", "Cuaderno de registro.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Pesa solo restos vegetales limpios; no manipules residuos que puedan ser peligrosos.", "No publiques los datos de tu hogar con información que lo identifique."], "otroSector": "La misma práctica de medir lo que se desperdicia sirve para estimar y reducir mermas en cualquier negocio."}$a20agr$::jsonb,27),
('cuanta-agua-necesita-realmente-un-cultivo-y-como-saber-cuando-da','agricultura',array['ambiente']::text[],'¿Cuánta agua necesita realmente un cultivo y cómo saber cuándo dársela?','Riega la misma planta con distintas cantidades de agua, aprende a leer las señales de falta o exceso y construye una guía sencilla para saber cuándo y cuánto regar.','Análisis','4 semanas',20,array['Necesidad de agua','Riego']::text[],array['investigar']::text[],'propios',NULL,'ingenieria agricola agronomia ingenieria ambiental ingenieria civil ingenieria sanitaria estadistica ingenieria de sistemas fisica observacion. medicion de volumenes. analisis de datos. comunicacion visual. macetas. jarra medidora. hoja de calculo.',$a21agr${"id": "cuanta-agua-necesita-realmente-un-cultivo-y-como-saber-cuando-da", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Cuánta agua necesita realmente un cultivo y cómo saber cuándo dársela?", "resumen": "Riega la misma planta con distintas cantidades de agua, aprende a leer las señales de falta o exceso y construye una guía sencilla para saber cuándo y cuánto regar.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 20, "etiquetas": ["Necesidad de agua", "Riego"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Agrícola", "Agronomía", "Ingeniería Ambiental", "Ingeniería Civil", "Ingeniería Sanitaria", "Estadística", "Ingeniería de Sistemas", "Física"], "problema": ["Se riega por costumbre más que por necesidad: tanto la falta como el exceso de agua dañan a las plantas, y los síntomas se parecen. Esto lleva a gastar agua de más o a perder plantas por ahogo.", "Aprender a reconocer las señales y medir lo que la planta realmente consume ayuda a regar con criterio."], "desarrollar": ["Siembra tres macetas iguales con la misma planta y riégalas con cantidades distintas pero constantes. Mide el volumen de agua y la humedad de la tierra con el dedo o con un palillo, y registra la altura y el aspecto de las hojas.", "Anota las señales que aparecen, como hojas caídas, amarillas o con manchas, y relaciónalas con la cantidad de agua. Elabora una guía de cuatro o cinco señales para decidir si regar, esperar o dejar de regar."], "ampliaciones": [{"titulo": "Tipo de planta", "aporta": "repite con otra planta y compara su necesidad de agua."}, {"titulo": "Prueba de humedad", "aporta": "crea una forma sencilla de comprobar la humedad sin dañar la planta."}, {"titulo": "Guía visual", "aporta": "ilustra las señales de falta y exceso de agua."}], "objetivos": ["Regar con cantidades distintas.", "Medir humedad y crecimiento.", "Reconocer señales de la planta.", "Elaborar una guía."], "habilidades": ["Observación.", "Medición de volúmenes.", "Análisis de datos.", "Comunicación visual."], "herramientas": ["Macetas.", "Jarra medidora.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Si usas agua de lluvia o reutilizada, riega solo el suelo y no las hojas de lo que vayas a comer, y lava bien lo que coseches.", "No uses pesticidas ni productos químicos en tu experimento; si una planta se enferma, anótalo como parte del registro."], "otroSector": "El mismo enfoque de ajustar la cantidad según señales sirve para dosificar insumos en cualquier proceso productivo."}$a21agr$::jsonb,28),
('que-metodo-de-riego-gasta-menos-agua','agricultura',array['ambiente']::text[],'¿Qué método de riego gasta menos agua?','Compara el consumo de agua y el crecimiento de plantas regadas con regadera, con botella invertida y con riego por goteo casero, para saber cuál ahorra más sin perjudicar la planta.','Análisis','4 semanas',22,array['Métodos de riego','Ahorro de agua']::text[],array['investigar']::text[],'propios',NULL,'ingenieria agricola agronomia ingenieria ambiental ingenieria civil ingenieria sanitaria estadistica ingenieria de sistemas fisica control de variables. medicion. analisis comparativo. graficas. regadera y botellas. jarra medidora. hoja de calculo.',$a22agr${"id": "que-metodo-de-riego-gasta-menos-agua", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Qué método de riego gasta menos agua?", "resumen": "Compara el consumo de agua y el crecimiento de plantas regadas con regadera, con botella invertida y con riego por goteo casero, para saber cuál ahorra más sin perjudicar la planta.", "tipo": "Análisis", "tiempo": "4 semanas", "horas": 22, "etiquetas": ["Métodos de riego", "Ahorro de agua"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Agrícola", "Agronomía", "Ingeniería Ambiental", "Ingeniería Civil", "Ingeniería Sanitaria", "Estadística", "Ingeniería de Sistemas", "Física"], "problema": ["Hay muchas formas de regar y cada una promete ahorrar agua, pero rara vez se compara con medidas. Regar a mano puede mojar demasiado en un solo momento, mientras que otros métodos entregan el agua de forma lenta y constante.", "Comparar con números ayuda a decidir qué método conviene para un huerto pequeño."], "desarrollar": ["Prepara tres grupos de plantas iguales y riégalos con tres métodos distintos, midiendo siempre cuánta agua usas en cada uno. Mantén igual la luz y el sustrato.", "Mide el crecimiento de las plantas y la humedad del suelo. Calcula cuánta agua usó cada método y qué crecimiento logró, y compara el resultado en una tabla y una gráfica. Concluye cuál recomendarías y por qué."], "ampliaciones": [{"titulo": "Más métodos", "aporta": "prueba el riego con mecha o con botellas enterradas."}, {"titulo": "Costos", "aporta": "compara cuánto cuesta armar cada método."}, {"titulo": "Esfuerzo", "aporta": "mide cuánto tiempo exige cada método por semana."}], "objetivos": ["Preparar métodos comparables.", "Medir el agua usada.", "Medir el crecimiento.", "Recomendar un método."], "habilidades": ["Control de variables.", "Medición.", "Análisis comparativo.", "Gráficas."], "herramientas": ["Regadera y botellas.", "Jarra medidora.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Si usas agua de lluvia o reutilizada, riega solo el suelo y no las hojas de lo que vayas a comer, y lava bien lo que coseches.", "Usa recipientes limpios y que no hayan contenido productos químicos."], "otroSector": "El mismo método de comparar consumos sirve para evaluar el gasto de agua o energía en un hogar o un negocio."}$a22agr$::jsonb,29)
